/**
 * Delete schedules exception rows that became orphaned after a ClassSession was moved
 * away from ($courseId, $oldDate, $oldStartTime).
 *
 * "Orphaned" means status='scheduled' but no ClassSession exists for this
 * (student_course_id, schedule_date, start_time) any more.
 *
 * We also delete the companion 'rescheduled' anchor rows when all their
 * 'scheduled' children have been removed.
 */
private function cleanOrphanedSchedulesForCourse(int $courseId, string $oldDate, string $oldStartTime): void
{
    // Guard: if another ClassSession still exists at oldDate+oldStartTime, don't touch anything.
    $stillHasSession = ClassSession::where('StudentClassID', $courseId)
        ->whereDate('SessionDate', $oldDate)
        ->where(DB::raw('SUBSTRING(StartTime, 1, 5)'), $oldStartTime)
        ->whereNotIn('Status', ['cancelled', 'voided'])
        ->exists();

    if ($stillHasSession) {
        return;
    }

    // Find scheduled (child) rows for this course on the old date/time.
    $orphanedScheduled = Schedule::where('student_course_id', $courseId)
        ->whereDate('schedule_date', $oldDate)
        ->where('status', 'scheduled')
        ->when(
            $oldStartTime !== '',
            fn ($q) => $q->where(DB::raw('SUBSTRING(start_time, 1, 5)'), $oldStartTime)
        )
        ->get();

    if ($orphanedScheduled->isEmpty()) {
        return;
    }

    $anchorIds = $orphanedScheduled->pluck('original_schedule_id')->filter()->unique();

    // Delete orphaned scheduled rows.
    Schedule::whereIn('id', $orphanedScheduled->pluck('id'))->delete();

    // Delete companion rescheduled (anchor) rows that no longer have any scheduled children.
    if ($anchorIds->isNotEmpty()) {
        Schedule::whereIn('id', $anchorIds)
            ->where('status', 'rescheduled')
            ->whereNotExists(function ($q) {
                $q->select(DB::raw(1))
                  ->from('schedules as child')
                  ->whereColumn('child.original_schedule_id', 'schedules.id')
                  ->where('child.status', 'scheduled');
            })
            ->delete();
    }
}

