    /**
     * POST /api/v1/admin/cleanup-orphaned-schedules
     *
     * Deletes schedules rows with status='scheduled' that have no corresponding
     * ClassSession for the same (student_course_id, schedule_date, start_time).
     * Also deletes their companion 'rescheduled' anchor rows when all children
     * are removed.
     *
     * Restricted to director / super_admin roles.
     * Supports optional dry_run=true to preview without deleting.
     */
    public function cleanupOrphanedSchedules(\Illuminate\Http\Request $request): \Illuminate\Http\JsonResponse
    {
        $dryRun = filter_var($request->input('dry_run', false), FILTER_VALIDATE_BOOLEAN);
        $authUser = $request->attributes->get('auth_user');
        $campusId = (int) ($authUser->branch_id ?? 0);

        // Step 1: Find all scheduled exception rows that have no matching ClassSession.
        // We match on (student_course_id, schedule_date, start_time[0:5]).
        // Only rows tied to a student_course_id (i.e. exception blocks, not standalone
        // teacher-only slots) are considered.
        $orphanedScheduled = Schedule::query()
            ->where('status', 'scheduled')
            ->whereNotNull('student_course_id')
            ->whereNotNull('schedule_date')
            ->when($campusId > 0, fn ($q) => $q->where('branch_id', $campusId))
            ->whereNotExists(function ($sub) {
                $sub->select(DB::raw(1))
                    ->from('ClassSession as cs')
                    ->whereColumn('cs.StudentClassID', 'schedules.student_course_id')
                    ->whereRaw('DATE(cs.SessionDate) = schedules.schedule_date')
                    ->whereRaw('SUBSTRING(cs.StartTime, 1, 5) = SUBSTRING(schedules.start_time, 1, 5)')
                    ->whereNotIn('cs.Status', ['cancelled', 'voided']);
            })
            ->get(['id', 'student_course_id', 'schedule_date', 'start_time', 'teacher_id', 'original_schedule_id', 'branch_id']);

        $orphanedIds    = $orphanedScheduled->pluck('id');
        $anchorIds      = $orphanedScheduled->pluck('original_schedule_id')->filter()->unique();

        // Step 2: Find 'rescheduled' anchor rows that will lose ALL their scheduled children.
        $orphanedAnchors = collect();
        if ($anchorIds->isNotEmpty()) {
            $orphanedAnchors = Schedule::whereIn('id', $anchorIds)
                ->where('status', 'rescheduled')
                ->whereNotExists(function ($q) use ($orphanedIds) {
                    // An anchor is safe to delete only when every one of its scheduled
                    // children is in the orphaned set (i.e. none will survive).
                    $q->select(DB::raw(1))
                      ->from('schedules as child')
                      ->whereColumn('child.original_schedule_id', 'schedules.id')
                      ->where('child.status', 'scheduled')
                      ->whereNotIn('child.id', $orphanedIds->toArray() ?: [0]);
                })
                ->get(['id', 'student_course_id', 'schedule_date', 'start_time', 'teacher_id']);
        }

        $result = [
            'orphaned_scheduled_count' => $orphanedScheduled->count(),
            'orphaned_anchor_count'    => $orphanedAnchors->count(),
            'dry_run'                  => $dryRun,
            'orphaned_scheduled'       => $orphanedScheduled->map(fn ($r) => [
                'id'                => $r->id,
                'student_course_id' => $r->student_course_id,
                'schedule_date'     => $r->schedule_date,
                'start_time'        => $r->start_time,
                'teacher_id'        => $r->teacher_id,
            ]),
            'orphaned_anchors' => $orphanedAnchors->map(fn ($r) => [
                'id'                => $r->id,
                'student_course_id' => $r->student_course_id,
                'schedule_date'     => $r->schedule_date,
                'start_time'        => $r->start_time,
            ]),
        ];

        if (!$dryRun) {
            DB::beginTransaction();
            try {
                $deletedScheduled = 0;
                $deletedAnchors   = 0;
                if ($orphanedIds->isNotEmpty()) {
                    $deletedScheduled = Schedule::whereIn('id', $orphanedIds)->delete();
                }
                if ($orphanedAnchors->isNotEmpty()) {
                    $deletedAnchors = Schedule::whereIn('id', $orphanedAnchors->pluck('id'))->delete();
                }
                DB::commit();
                $result['deleted_scheduled'] = $deletedScheduled;
                $result['deleted_anchors']   = $deletedAnchors;
                $result['message']           = "已刪除 {$deletedScheduled} 筆孤兒 scheduled 紀錄、{$deletedAnchors} 筆孤兒 rescheduled 錨點。";
            } catch (\Throwable $e) {
                DB::rollBack();
                return response()->json(['message' => '清理失敗：' . $e->getMessage()], 500);
            }
        } else {
            $result['message'] = "（dry-run）找到 {$orphanedScheduled->count()} 筆孤兒 scheduled、{$orphanedAnchors->count()} 筆孤兒 rescheduled 可刪除。";
        }

        return response()->json($result);
    }
}

