use Illuminate\Support\Facades\DB;

// Count orphaned scheduled rows (status='scheduled', no matching ClassSession)
$orphanedScheduled = DB::select("
    SELECT s.id, s.student_course_id, s.schedule_date, s.start_time, s.teacher_id, s.original_schedule_id
    FROM schedules s
    WHERE s.status = 'scheduled'
      AND s.student_course_id IS NOT NULL
      AND s.schedule_date IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM ClassSession cs
        WHERE cs.StudentClassID = s.student_course_id
          AND DATE(cs.SessionDate) = s.schedule_date
          AND SUBSTRING(cs.StartTime, 1, 5) = SUBSTRING(s.start_time, 1, 5)
          AND cs.Status NOT IN ('cancelled', 'voided')
      )
    ORDER BY s.schedule_date DESC
    LIMIT 50
");

echo "=== Orphaned 'scheduled' rows (" . count($orphanedScheduled) . " found) ===\n";
foreach ($orphanedScheduled as $r) {
    echo "  id={$r->id} course={$r->student_course_id} date={$r->schedule_date} time={$r->start_time} teacher={$r->teacher_id} original_id={$r->original_schedule_id}\n";
}

// Count orphaned rescheduled anchor rows
$anchorIds = collect($orphanedScheduled)->pluck('original_schedule_id')->filter()->unique()->toArray();
$orphanedAnchors = [];
if (!empty($anchorIds)) {
    $placeholders = implode(',', $anchorIds);
    $orphanedIds = collect($orphanedScheduled)->pluck('id')->toArray();
    $orphanIdsStr = implode(',', $orphanedIds ?: [0]);
    $orphanedAnchors = DB::select("
        SELECT s.id, s.student_course_id, s.schedule_date, s.start_time
        FROM schedules s
        WHERE s.id IN ($placeholders)
          AND s.status = 'rescheduled'
          AND NOT EXISTS (
            SELECT 1 FROM schedules child
            WHERE child.original_schedule_id = s.id
              AND child.status = 'scheduled'
              AND child.id NOT IN ($orphanIdsStr)
          )
    ");
}

echo "\n=== Orphaned 'rescheduled' anchors (" . count($orphanedAnchors) . " found) ===\n";
foreach ($orphanedAnchors as $r) {
    echo "  id={$r->id} course={$r->student_course_id} date={$r->schedule_date} time={$r->start_time}\n";
}

echo "\nTotal to be deleted: " . (count($orphanedScheduled) + count($orphanedAnchors)) . " rows\n";
